    // More of it, as (path it leads to, or null; selector), e.g.:
    // SEARCH_BUTTON(null, "css=header button[aria-label='Search']"),
    // ==== END YOURS (elements) ====
    ;

    private final String path;
    private final String selector;

    HeaderElements(String path, String selector) {
        this.path = path;
        this.selector = selector;
    }

    /** The path this link leads to, e.g. "/about"; null for what opens a dropdown. */
    public String path() {
        return path;
    }

    /** The element where it is visible. A link inside a closed dropdown has none until it opens. */
    @Override
    public Locator locator(Page page) {
        return page.locator(selector + " >> visible=true").first();
    }

    /** True when it can be clicked as the page loaded (not only inside a dropdown). */
    public boolean isVisibleOn(Page page) {
        return page.locator(selector + " >> visible=true").count() > 0;
    }
